1	#!/usr/bin/env bash
2	# ship-pr.sh — Deterministic /implement post-review state machine.
3	
4	set -uo pipefail
5	# Intentionally no `set -e`: this script composes best-effort helpers whose
6	# outcome is communicated through stdout envelopes. Each helper call captures
7	# rc explicitly so state can be checkpointed before returning to SKILL.md.
8	LC_ALL=C
9	export LC_ALL
