59	append_unique_paths_file() {
60	    local target=$1 source=${2:-}
61	    [[ -n "$target" && -n "$source" && -f "$source" ]] || return 0
62	    mkdir -p "$(dirname "$target")"
63	    if [[ -f "$target" ]]; then
64	        awk 'NF && !seen[$0]++ { print }' "$target" "$source" > "${target}.tmp" && mv "${target}.tmp" "$target"
65	    else
66	        awk 'NF && !seen[$0]++ { print }' "$source" > "$target"
67	    fi
68	}
