70	run_lint_fix_loop_capture() {
71	    local fail_file=$1 site=$2 redacted_log=$3 out_var=$4 rc_var=$5
72	    local output rc had_errexit=0
73	    case $- in *e*) had_errexit=1 ;; esac
74	    set +e
75	    output=$("$SCRIPT_DIR/lint-fix-loop.sh" \
76	        --tmpdir "$IMPLEMENT_TMPDIR" \
77	        --site "$site" \
78	        --checks-log "$redacted_log" 2>"$fail_file")
79	    rc=$?
80	    (( had_errexit )) && set -e
81	    printf -v "$out_var" '%s' "$output"
82	    printf -v "$rc_var" '%s' "$rc"
83	}
