85	collect_ci_stage_paths() {
86	    local vendor_tracked_dirty_file=$1 vendor_untracked_dirty_file=$2 tracked_dirty_file=$3 untracked_dirty_file=$4 allowlisted_delta_file=$5
87	    awk '
88	        FNR == NR {
89	            if (NF) vendor_tracked[$0]=1
90	            next
91	        }
92	        FILENAME == ARGV[2] {
93	            if (NF) vendor_untracked[$0]=1
94	            next
95	        }
96	        FILENAME == ARGV[3] {
97	            if (NF && !seen[$0]++) print
98	            next
99	        }
100	        FILENAME == ARGV[4] {
101	            if (NF) current_untracked[$0]=1
102	            next
103	        }
104	        {
105	            if (!NF || seen[$0]++) next
106	            if (current_untracked[$0]) print
107	        }
108	    ' \
109	        "${vendor_tracked_dirty_file:-/dev/null}" \
110	        "${vendor_untracked_dirty_file:-/dev/null}" \
111	        "${tracked_dirty_file:-/dev/null}" \
112	        "${untracked_dirty_file:-/dev/null}" \
113	        "${allowlisted_delta_file:-/dev/null}"
114	}
