126	is_tmp_path() {
127	    local cache_root
128	    cache_root="${XDG_CACHE_HOME:-${HOME:-/tmp}/.cache}/larch/sessions"
129	    case "$1" in
130	        /tmp/*|/private/tmp/*|/var/folders/*|/private/var/folders/*) return 0 ;;
131	        "$cache_root"/*) return 0 ;;
132	        *) return 1 ;;
133	    esac
134	}
