153	[ -n "$STATE_FILE" ] || die_usage "--state-file is required"
154	[ -n "$IMPLEMENT_TMPDIR" ] || die_usage "--implement-tmpdir is required"
155	is_tmp_path "$STATE_FILE" || die_usage "--state-file must be under /tmp/, /private/tmp/, /var/folders/, or the larch cache sessions root"
156	is_tmp_path "$IMPLEMENT_TMPDIR" || die_usage "--implement-tmpdir must be under /tmp/, /private/tmp/, /var/folders/, or the larch cache sessions root"
157	[ -d "$IMPLEMENT_TMPDIR" ] || die_usage "--implement-tmpdir must exist"
158	case "$STATE_FILE" in "$IMPLEMENT_TMPDIR"/*) ;; *) die_usage "--state-file must live under --implement-tmpdir" ;; esac
159	is_bool "$AUTO_MODE" || die_usage "--auto-mode must be true or false"
160	is_bool "$NO_ADMIN_FALLBACK" || die_usage "--no-admin-fallback must be true or false"
161	is_bool "$NO_LOGS_COMMIT" || die_usage "--no-logs-commit must be true or false"
162	[ -z "$MERGE" ] || is_bool "$MERGE" || die_usage "--merge must be true or false"
163	[ -z "$DRAFT" ] || is_bool "$DRAFT" || die_usage "--draft must be true or false"
164	[ -z "$FORKED_TARGET" ] || is_bool "$FORKED_TARGET" || die_usage "--forked must be true or false"
165	# Export so child processes inherit the session tmpdir path regardless of
166	# whether the caller shell already had it exported (e.g. after a session
167	# restart where the orchestrator env was fresh). Log helpers resolve their run
168	# context from this tmpdir.
169	export IMPLEMENT_TMPDIR
170	export LARCH_NO_LOGS_COMMIT="$NO_LOGS_COMMIT"
