172	validate_state_syntax() {
173	    local line line_no
174	    line_no=0
175	    while IFS= read -r line || [ -n "$line" ]; do
176	        line_no=$((line_no + 1))
177	        case "$line" in ""|\#*) continue ;; esac
178	        if ! printf '%s\n' "$line" | grep -Eq '^[A-Z_][A-Z0-9_]*=.*$'; then
179	            die_usage "malformed state-file line $line_no"
180	        fi
181	    done < "$STATE_FILE"
182	}
